      return recorded.map(function (s) { return '<path d="' + pathD(s.map(function (p) { return [p[0], p[1]]; }), 0) + '" fill="none" stroke="' + stroke() + '" stroke-width="' + st.size + '" stroke-linecap="round" stroke-linejoin="round"/>'; }).join('');
